<?php require 'config.php'; $message=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)&&strlen($password)>=8){$q=db()->prepare('INSERT INTO admins(name,email,password_hash) VALUES(?,?,?)');$q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$message='Admin created. Delete setup_admin.php from the server now.';}else $message='Enter a name, valid email and password of at least 8 characters.';} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Admin</title><link rel="stylesheet" href="assets/css/style.css"></head><body class="admin-login"><div class="login-card"><img src="assets/images/school-logo.png"><h1>Create Admin</h1><p><?=e($message)?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="8" required></label><button class="btn">Create Admin</button></form></div></body></html>
